"""Tests for the Node model and NodeType enum."""

from __future__ import annotations

from pathlib import Path

from depcycle.graph.edge import Edge
from depcycle.graph.node import Node, NodeType


def test_node_type_enum() -> None:
    """Verify NodeType enumeration values."""
    assert NodeType.LOCAL.value == "local"
    assert NodeType.THIRD_PARTY.value == "third_party"
    assert NodeType.STDLIB.value == "stdlib"
    assert NodeType.UNKNOWN.value == "unknown"


def test_node_defaults_and_fields() -> None:
    """Test default values when initializing a Node."""
    node = Node(name="my.module")

    assert node.name == "my.module"
    assert node.file_path is None
    assert node.node_type is NodeType.UNKNOWN
    assert node.raw_imports == set()
    assert node.outgoing_edges == set()
    assert node.dependencies == set()


def test_node_custom_fields() -> None:
    """Test initializing a Node with explicit metadata and imports."""
    file_path = Path("/project/example.py")
    imports = {"os", "requests"}

    node = Node(
        name="example",
        file_path=file_path,
        node_type=NodeType.LOCAL,
        raw_imports=imports,
    )

    assert node.name == "example"
    assert node.file_path == file_path
    assert node.node_type is NodeType.LOCAL
    assert node.raw_imports == imports
    assert node.outgoing_edges == set()


def test_add_dependency() -> None:
    """Test adding an outgoing dependency edge."""
    n1 = Node(name="mod.a")
    n2 = Node(name="mod.b")

    edge = n1.add_dependency(n2)

    assert isinstance(edge, Edge)
    assert edge.source is n1
    assert edge.target is n2
    assert edge in n1.outgoing_edges
    assert n1.dependencies == {n2}


def test_add_duplicate_dependency_is_deduplicated() -> None:
    """Test that adding the same dependency twice creates one edge."""
    source = Node(name="source")
    target = Node(name="target")

    first = source.add_dependency(target)
    second = source.add_dependency(target)

    assert first == second
    assert len(source.outgoing_edges) == 1
    assert source.dependencies == {target}


def test_dependencies_returns_targets() -> None:
    """Test that dependencies exposes target nodes from outgoing edges."""
    source = Node(name="source")
    target_a = Node(name="a")
    target_b = Node(name="b")

    source.add_dependency(target_a)
    source.add_dependency(target_b)

    assert source.dependencies == {target_a, target_b}


def test_node_equality_and_hashing() -> None:
    """Test custom name-based equality and hashing."""
    n1 = Node(name="foo", node_type=NodeType.LOCAL)
    n2 = Node(name="foo", node_type=NodeType.STDLIB)
    n3 = Node(name="bar")

    assert n1 == n2
    assert n1 != n3
    assert n1 != "not-a-node"  # type: ignore[comparison-overlap]

    assert hash(n1) == hash(n2)
    assert hash(n1) != hash(n3)

    node_set = {n1, n2, n3}
    assert len(node_set) == 2


def test_node_repr() -> None:
    """Test the Node string representation."""
    node = Node(name="depcycle.core", node_type=NodeType.LOCAL)

    assert repr(node) == "Node(name='depcycle.core', type=LOCAL, edges=0)"


def test_node_repr_includes_edge_count() -> None:
    """Test that Node repr reports the current outgoing edge count."""
    source = Node(name="source")
    target = Node(name="target")

    source.add_dependency(target)

    assert repr(source) == "Node(name='source', type=UNKNOWN, edges=1)"
